$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"

$modulePath = Join-Path $pkg "ahos\visual_pipeline.py"
$testPath = Join-Path $pkg "tests\test_visual_pipeline.py"
$backlogPath = Join-Path $pkg "STUDIO_BACKLOG.json"
$reportPath = Join-Path $pkg "reports\STUDIO-005-visual-pipeline-proof.json"

$privateRoot = Join-Path $root "runtime\private\animation-studio"
$graphPath = Join-Path $privateRoot "episodes\S01E001\production-graph.local.json"
$renderDb = Join-Path $privateRoot "render-manifest.db"
$renderManifest = Join-Path $privateRoot "episodes\S01E001\render-manifest.local.json"
$workflowContract = Join-Path $privateRoot "comfyui\workflow-contract.local.json"

$patcher = Join-Path $env:TEMP "studio-005-backlog.py"
$proof = Join-Path $env:TEMP "studio-005-proof.py"

Write-Host "=== STUDIO-005 VISUAL GENERATION + COMFYUI ADAPTER ==="
Write-Host "LOCALHOST COMFYUI ONLY"
Write-Host "Render submissions during install: 0"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""

if (-not (Test-Path $python)) { throw "Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }
if (-not (Test-Path $graphPath)) {
    throw "STUDIO-004 production graph missing: $graphPath"
}

New-Item -ItemType Directory -Force -Path (Split-Path $reportPath -Parent) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path $renderManifest -Parent) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path $workflowContract -Parent) | Out-Null

[IO.File]::WriteAllBytes(
    $modulePath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $patcher,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $proof,
    [Convert]::FromBase64String("")
)

$old = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg

    Write-Host "Running Visual Pipeline focused tests..."
    & $python -m pytest tests\test_visual_pipeline.py -q
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-005 focused tests failed."
    }

    Write-Host "Running full AHOS + Studio regression suite..."
    & $python -m pytest -q
    if ($LASTEXITCODE -ne 0) {
        throw "Full regression suite failed."
    }

    Write-Host "Creating private render manifest and probing local ComfyUI..."
    & $python $proof $graphPath $renderDb $renderManifest $workflowContract $reportPath
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-005 local proof failed."
    }

    & $python $patcher $backlogPath
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-005 backlog update failed."
    }
}
finally {
    Pop-Location
    $env:PYTHONPATH = $old
    Remove-Item $patcher -Force -ErrorAction SilentlyContinue
    Remove-Item $proof -Force -ErrorAction SilentlyContinue
}

$repoResolved = [IO.Path]::GetFullPath($ws)
$privateResolved = [IO.Path]::GetFullPath($privateRoot)
if ($privateResolved.StartsWith($repoResolved, [StringComparison]::OrdinalIgnoreCase)) {
    throw "Privacy guard failed: private render data is inside Git repository."
}

git -C $ws add `
    ahos_core/ahos/visual_pipeline.py `
    ahos_core/tests/test_visual_pipeline.py `
    ahos_core/STUDIO_BACKLOG.json `
    ahos_core/reports/STUDIO-005-visual-pipeline-proof.json

$staged = git -C $ws diff --cached --name-only
if ($staged -match "render-manifest\.db|render-manifest\.local|workflow-contract\.local|production-graph\.local") {
    throw "Privacy guard failed: private visual pipeline data was staged."
}

if ($staged) {
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" `
        commit -m "feat(studio): add guarded ComfyUI visual pipeline"
    if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

    git -C $ws push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw "git push failed." }
}

$report = Get-Content $reportPath -Raw | ConvertFrom-Json

Write-Host ""
Write-Host "=== STUDIO-005 COMPLETE ==="
Write-Host "Production graph -> deterministic render jobs: PASS"
Write-Host "Persistent render manifest DB: PASS"
Write-Host "Localhost-only ComfyUI client: PASS"
Write-Host "ComfyUI health + node inventory: PASS"
Write-Host "Workflow API JSON placeholder contract: PASS"
Write-Host "Owner approval gate: PASS"
Write-Host "Execution enable gate: PASS"
Write-Host "Actual render submissions: 0"
Write-Host "Private visual data kept OUTSIDE Git: PASS"
Write-Host "Full regression suite: PASS"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""
Write-Host "COMFYUI REACHABLE NOW:" $report.comfyui_reachable_now
Write-Host "COMFYUI NODE COUNT:" $report.comfyui_node_count
if (-not $report.comfyui_reachable_now) {
    Write-Host "NOTE: Adapter is ready; ComfyUI server was not running/reachable during this probe."
}
Write-Host "NEXT: STUDIO-006 voice, music, dubbing and localization pipeline."
